SELECT 444 f,n.profile profile,CASE WHEN (n.published_at+ifnull(n.published_offset,0)*60)/86400=19326 THEN 'b001' WHEN (n.published_at+ifnull(n.published_offset,0)*60)/86400>19297 THEN 'b002' WHEN (n.published_at+ifnull(n.published_offset,0)*60)/86400>19147 THEN 'b030' WHEN (n.published_at+ifnull(n.published_offset,0)*60)/86400>18962 THEN 'b180' ELSE 'b365' END pb,n.dispatched_at IS NOT NULL d,count(DISTINCT n.id) stale,count(DISTINCT CASE WHEN v.tender_id IS NOT NULL THEN n.id END) with_v,count(v.tender_id) vers,sum(EXISTS(SELECT 1 FROM tender_versions x WHERE x.tender_id=v.tender_id AND x.seq<>v.seq)) multi,0 r_doe,sum(EXISTS(SELECT 1 FROM tender_versions x JOIN notices m ON m.id=x.caused_by_notice_id WHERE x.tender_id=v.tender_id AND x.seq>v.seq AND m.source<>'doe' AND x.published_at<1669852800)) r_ted,sum(EXISTS(SELECT 1 FROM tender_versions x WHERE x.tender_id=v.tender_id AND x.seq>v.seq AND x.published_at<1669852800)) r_pub FROM notices n LEFT JOIN tender_versions v ON v.caused_by_notice_id=n.id WHERE n.fetch_id=444 AND +n.id>=1000000 AND n.published_at IS NOT NULL AND (n.published_at+ifnull(n.published_offset,0)*60)/86400<19327 GROUP BY +n.profile,pb,d
